"""Generate the full HTML report for Global Intentional Homicide Trends."""
import pandas as pd
import numpy as np
import json
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import io, base64
from textwrap import dedent

plt.rcParams.update({
    "font.family": "sans-serif",
    "font.size": 11,
    "axes.titlesize": 13,
    "axes.labelsize": 11,
    "xtick.labelsize": 10,
    "ytick.labelsize": 10,
    "figure.facecolor": "white",
    "axes.facecolor": "#fafbfc",
    "axes.edgecolor": "#d1d5db",
    "axes.grid": True,
    "grid.alpha": 0.4,
    "grid.color": "#d1d5db",
})

ACCENT = "#1e3a5f"
COLORS = ["#1e3a5f", "#c0392b", "#27ae60", "#f39c12", "#8e44ad", "#2980b9", "#e67e22", "#16a085"]
REGION_COLORS = {
    "Americas": "#c0392b",
    "Africa": "#f39c12",
    "Asia": "#2980b9",
    "Europe": "#27ae60",
    "Oceania": "#8e44ad",
    "Other": "#7f8c8d",
}

with open("/app/scripts/results.json") as f:
    R = json.load(f)

df = pd.read_csv("/app/benchmark/data.csv")

# ---- helper ----
def fig_to_b64(fig, dpi=140):
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode()

def img_tag(b64, alt="chart", extra_style=""):
    return f'<img src="data:image/png;base64,{b64}" alt="{alt}" style="max-width:100%;height:auto;border-radius:6px;{extra_style}" />'

# ==========================
# CHART 1: Global trend line (mean & median)
# ==========================
fig, ax = plt.subplots(figsize=(10, 4.5))
years = R["yearly"]["year"]
ax.plot(years, R["yearly"]["mean_rate"], color=COLORS[0], linewidth=2.2, marker="o", markersize=4, label="Mean rate")
ax.plot(years, R["yearly"]["median_rate"], color=COLORS[1], linewidth=2.2, marker="s", markersize=4, label="Median rate")
ax.set_xlabel("Year")
ax.set_ylabel("Homicide Rate per 100k")
ax.set_title("Global Homicide Rate Trend (1990–2023)")
ax.legend(frameon=True, facecolor="white")
ax.set_xlim(1989, 2024)
ax.xaxis.set_major_locator(mticker.MultipleLocator(5))
chart_trend = fig_to_b64(fig)

# ==========================
# CHART 2: Reporting coverage
# ==========================
fig, ax = plt.subplots(figsize=(10, 3.5))
ax.bar(R["coverage"]["year"], R["coverage"]["n"], color=ACCENT, alpha=0.85)
ax.set_xlabel("Year")
ax.set_ylabel("Number of Countries Reporting")
ax.set_title("Reporting Coverage Over Time")
ax.set_xlim(1989, 2024)
ax.xaxis.set_major_locator(mticker.MultipleLocator(5))
chart_coverage = fig_to_b64(fig)

# ==========================
# CHART 3: Regional median trends
# ==========================
main = df[(df["sex"] == "both") & (df["age_group"] == "ALL")].copy()
REGIONS_MAP = {}
for iso, reg in json.loads(open("/app/scripts/analyze.py").read().split("REGIONS = ")[1].split("\n}")[0] + "\n}"):
    pass  # we'll rebuild from data
# Rebuild region mapping inline
exec_globals = {}
code_str = open("/app/scripts/analyze.py").read()
idx_start = code_str.index("REGIONS = {")
idx_end = code_str.index("\n}", idx_start) + 2
exec(code_str[idx_start:idx_end], exec_globals)
REGIONS_MAP = exec_globals["REGIONS"]
main["region"] = main["iso_code"].map(REGIONS_MAP).fillna("Other")

fig, ax = plt.subplots(figsize=(10, 5))
for region in ["Americas", "Africa", "Asia", "Europe", "Oceania"]:
    rdata = main[main["region"] == region].groupby("year")["homicide_rate"].median()
    ax.plot(rdata.index, rdata.values, linewidth=2, label=region, color=REGION_COLORS[region])
ax.set_xlabel("Year")
ax.set_ylabel("Median Homicide Rate per 100k")
ax.set_title("Median Homicide Rate by Region (1990–2023)")
ax.legend(frameon=True, facecolor="white")
ax.set_xlim(1989, 2024)
ax.xaxis.set_major_locator(mticker.MultipleLocator(5))
chart_regional = fig_to_b64(fig)

# ==========================
# CHART 4: Top 10 & bottom 10 bar
# ==========================
fig, axes = plt.subplots(1, 2, figsize=(12, 5), gridspec_kw={"width_ratios": [1.2, 1]})

top = pd.DataFrame(R["top10"]).sort_values("homicide_rate")
axes[0].barh(top["country"], top["homicide_rate"], color="#c0392b", alpha=0.85)
axes[0].set_xlabel("Rate per 100k")
axes[0].set_title(f"Highest Homicide Rates ({R['recent_year']})")
for i, v in enumerate(top["homicide_rate"]):
    axes[0].text(v + 0.5, i, f"{v:.1f}", va="center", fontsize=9)

bot = pd.DataFrame(R["bottom10"]).sort_values("homicide_rate", ascending=False)
axes[1].barh(bot["country"], bot["homicide_rate"], color="#27ae60", alpha=0.85)
axes[1].set_xlabel("Rate per 100k")
axes[1].set_title(f"Lowest Homicide Rates ({R['recent_year']})")
for i, v in enumerate(bot["homicide_rate"]):
    axes[1].text(v + 0.01, i, f"{v:.2f}", va="center", fontsize=9)

fig.tight_layout(pad=2)
chart_top_bottom = fig_to_b64(fig)

# ==========================
# CHART 5: Gender disparity over time
# ==========================
sex_y = pd.DataFrame(R["sex_yearly"])
fig, ax1 = plt.subplots(figsize=(10, 4.5))
ax1.plot(sex_y["year"], sex_y["male"], color="#2980b9", linewidth=2.2, marker="o", markersize=4, label="Male median")
ax1.plot(sex_y["year"], sex_y["female"], color="#e74c3c", linewidth=2.2, marker="s", markersize=4, label="Female median")
ax1.set_xlabel("Year")
ax1.set_ylabel("Median Homicide Rate per 100k")
ax1.set_title("Homicide Rates by Sex (Median Across Countries)")
ax1.legend(loc="upper left", frameon=True, facecolor="white")
ax1.set_xlim(1989, 2024)
ax1.xaxis.set_major_locator(mticker.MultipleLocator(5))

ax2 = ax1.twinx()
ax2.plot(sex_y["year"], sex_y["ratio"], color="#8e44ad", linewidth=1.5, linestyle="--", alpha=0.7, label="Male:Female ratio")
ax2.set_ylabel("Male:Female Ratio", color="#8e44ad")
ax2.tick_params(axis="y", labelcolor="#8e44ad")
ax2.legend(loc="upper right", frameon=True, facecolor="white")
chart_gender = fig_to_b64(fig)

# ==========================
# CHART 6: Gender ratio bar by selected countries (latest year)
# ==========================
sex_data = df[(df["age_group"] == "ALL") & (df["sex"].isin(["male", "female"]))]
latest_sex = sex_data.sort_values("year").groupby(["country", "sex"]).last().reset_index()
pivot_sex = latest_sex.pivot(index="country", columns="sex", values="homicide_rate").dropna()
pivot_sex["ratio"] = pivot_sex["male"] / pivot_sex["female"]
pivot_sex_top = pivot_sex.nlargest(15, "ratio").sort_values("ratio")

fig, ax = plt.subplots(figsize=(10, 5))
ax.barh(pivot_sex_top.index, pivot_sex_top["ratio"], color=ACCENT, alpha=0.85)
ax.set_xlabel("Male-to-Female Homicide Rate Ratio")
ax.set_title("Countries with Highest Gender Disparity in Homicide Rates")
for i, (_, row) in enumerate(pivot_sex_top.iterrows()):
    ax.text(row["ratio"] + 0.2, i, f"{row['ratio']:.1f}×", va="center", fontsize=9)
chart_gender_countries = fig_to_b64(fig)

# ==========================
# CHART 7: Age group analysis
# ==========================
age_data = df[(df["age_group"] != "ALL")]
# average across male + female
age_mean = age_data.groupby("age_group")["homicide_rate"].agg(["mean", "median"]).reset_index()
age_order = ["0_9", "10_14", "15_17", "18_19", "20_24", "25_29", "30_44", "45_59", "60_PLUS"]
age_labels = ["0-9", "10-14", "15-17", "18-19", "20-24", "25-29", "30-44", "45-59", "60+"]
age_mean["age_group"] = pd.Categorical(age_mean["age_group"], categories=age_order, ordered=True)
age_mean = age_mean.sort_values("age_group")

fig, ax = plt.subplots(figsize=(10, 4.5))
x = range(len(age_mean))
ax.bar(x, age_mean["mean"], color=ACCENT, alpha=0.85, label="Mean")
ax.bar(x, age_mean["median"], color=COLORS[1], alpha=0.65, label="Median")
ax.set_xticks(x)
ax.set_xticklabels(age_labels)
ax.set_xlabel("Age Group")
ax.set_ylabel("Homicide Rate per 100k")
ax.set_title("Homicide Rates by Age Group (Global Average)")
ax.legend(frameon=True, facecolor="white")
chart_age = fig_to_b64(fig)

# ==========================
# CHART 7b: Age group by sex
# ==========================
age_sex = age_data.groupby(["age_group", "sex"])["homicide_rate"].mean().unstack()
age_sex = age_sex.reindex(age_order)

fig, ax = plt.subplots(figsize=(10, 4.5))
x = np.arange(len(age_order))
w = 0.35
ax.bar(x - w/2, age_sex["male"], width=w, color="#2980b9", alpha=0.85, label="Male")
ax.bar(x + w/2, age_sex["female"], width=w, color="#e74c3c", alpha=0.85, label="Female")
ax.set_xticks(x)
ax.set_xticklabels(age_labels)
ax.set_xlabel("Age Group")
ax.set_ylabel("Mean Homicide Rate per 100k")
ax.set_title("Homicide Rates by Age Group and Sex")
ax.legend(frameon=True, facecolor="white")
chart_age_sex = fig_to_b64(fig)

# ==========================
# CHART 8: Notable outliers — biggest changes
# ==========================
# Select a few interesting country time series
outlier_countries_dec = ["El Salvador", "Colombia", "South Africa"]
outlier_countries_inc = ["Ecuador", "Haiti", "Jamaica"]

fig, axes = plt.subplots(1, 2, figsize=(12, 4.5))
for country in outlier_countries_dec:
    cdata = main[main["country"] == country].sort_values("year")
    axes[0].plot(cdata["year"], cdata["homicide_rate"], marker="o", markersize=3, linewidth=1.8, label=country)
axes[0].set_title("Notable Decreases")
axes[0].set_xlabel("Year")
axes[0].set_ylabel("Rate per 100k")
axes[0].legend(frameon=True, facecolor="white")
axes[0].xaxis.set_major_locator(mticker.MultipleLocator(5))

for country in outlier_countries_inc:
    cdata = main[main["country"] == country].sort_values("year")
    axes[1].plot(cdata["year"], cdata["homicide_rate"], marker="o", markersize=3, linewidth=1.8, label=country)
axes[1].set_title("Notable Increases")
axes[1].set_xlabel("Year")
axes[1].set_ylabel("Rate per 100k")
axes[1].legend(frameon=True, facecolor="white")
axes[1].xaxis.set_major_locator(mticker.MultipleLocator(5))

fig.tight_layout(pad=2)
chart_outliers = fig_to_b64(fig)

# ==========================
# CHART 9: Decade-over-decade
# ==========================
dec = pd.DataFrame(R["decades"])
fig, ax = plt.subplots(figsize=(8, 4))
x = range(len(dec))
bars = ax.bar(x, dec["mean_rate"], color=[COLORS[i] for i in range(len(dec))], alpha=0.85)
ax.bar(x, dec["median_rate"], color=[COLORS[i] for i in range(len(dec))], alpha=0.4)
ax.set_xticks(x)
ax.set_xticklabels([f"{d}s" for d in dec["decade"].astype(int)])
ax.set_ylabel("Homicide Rate per 100k")
ax.set_title("Mean and Median Homicide Rates by Decade")
for i, (m, md) in enumerate(zip(dec["mean_rate"], dec["median_rate"])):
    ax.text(i, m + 0.2, f"Mean: {m:.1f}", ha="center", fontsize=9, fontweight="bold")
    ax.text(i, md + 0.2, f"Med: {md:.1f}", ha="center", fontsize=8, color="#555")
chart_decades = fig_to_b64(fig)

# ==========================
# BUILD HTML REPORT
# ==========================

# Helper for KPI cards
kpi = R["kpi"]
dec_changes = kpi["dec_change"]

# Format decade changes
def fmt_change(v):
    sign = "+" if v > 0 else ""
    return f"{sign}{v:.1f}%"

dec_00_10 = fmt_change(dec_changes["2000s_to_2010s"])
dec_10_20 = fmt_change(dec_changes["2010s_to_2020s"])
dec_90_00 = fmt_change(dec_changes["1990s_to_2000s"])

# Build tables
def html_table(records, columns, headers=None, highlight_col=None, fmt_fn=None):
    if headers is None:
        headers = columns
    rows = []
    for rec in records:
        cells = []
        for c in columns:
            val = rec[c]
            if fmt_fn and c in fmt_fn:
                val = fmt_fn[c](val)
            hl = ""
            if highlight_col and c == highlight_col:
                if isinstance(val, (int, float)):
                    color = "#c0392b" if val > 0 else "#27ae60" if val < 0 else "#333"
                    hl = f' style="color:{color};font-weight:600"'
            cells.append(f"<td{hl}>{val}</td>")
        rows.append("<tr>" + "".join(cells) + "</tr>")
    hdr = "".join(f"<th>{h}</th>" for h in headers)
    return f'<table class="data-table"><thead><tr>{hdr}</tr></thead><tbody>{"".join(rows)}</tbody></table>'

# Format outlier tables
def fmt_rate(v):
    return f"{v:.2f}"
def fmt_pct(v):
    sign = "+" if v > 0 else ""
    return f"{sign}{v:.1f}%"
def fmt_yr(v):
    return str(int(v))
def fmt_abs(v):
    sign = "+" if v > 0 else ""
    return f"{sign}{v:.1f}"

top10_tbl = html_table(R["top10"], ["country", "homicide_rate"],
    ["Country", "Rate per 100k"], fmt_fn={"homicide_rate": fmt_rate})
bot10_tbl = html_table(R["bottom10"], ["country", "homicide_rate"],
    ["Country", "Rate per 100k"], fmt_fn={"homicide_rate": fmt_rate})

big_dec_tbl = html_table(R["big_dec"],
    ["country", "first_year", "first_rate", "last_year", "last_rate", "abs_change", "pct_change"],
    ["Country", "From Year", "From Rate", "To Year", "To Rate", "Abs. Change", "% Change"],
    highlight_col="abs_change",
    fmt_fn={"first_rate": fmt_rate, "last_rate": fmt_rate, "abs_change": fmt_abs,
            "pct_change": fmt_pct, "first_year": fmt_yr, "last_year": fmt_yr})

big_inc_tbl = html_table(R["big_inc"],
    ["country", "first_year", "first_rate", "last_year", "last_rate", "abs_change", "pct_change"],
    ["Country", "From Year", "From Rate", "To Year", "To Rate", "Abs. Change", "% Change"],
    highlight_col="abs_change",
    fmt_fn={"first_rate": fmt_rate, "last_rate": fmt_rate, "abs_change": fmt_abs,
            "pct_change": fmt_pct, "first_year": fmt_yr, "last_year": fmt_yr})

reg_tbl = html_table(R["reg_recent"],
    ["region", "median_rate", "mean_rate", "n_countries"],
    ["Region", "Median Rate", "Mean Rate", "Countries"],
    fmt_fn={"median_rate": fmt_rate, "mean_rate": fmt_rate})

# Age table
age_stats_raw = age_data.groupby("age_group")["homicide_rate"].agg(["mean", "median", "count"]).reset_index()
age_stats_raw["age_group"] = pd.Categorical(age_stats_raw["age_group"], categories=age_order, ordered=True)
age_stats_raw = age_stats_raw.sort_values("age_group")
age_tbl_data = []
for _, row in age_stats_raw.iterrows():
    lbl = age_labels[age_order.index(row["age_group"])]
    age_tbl_data.append({"age_group": lbl, "mean": row["mean"], "median": row["median"], "count": int(row["count"])})
age_tbl = html_table(age_tbl_data,
    ["age_group", "mean", "median", "count"],
    ["Age Group", "Mean Rate", "Median Rate", "Observations"],
    fmt_fn={"mean": fmt_rate, "median": fmt_rate})

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
<style>
  :root {{
    --accent: #1e3a5f;
    --accent-light: #2c5282;
    --bg: #ffffff;
    --surface: #f8fafc;
    --border: #e2e8f0;
    --text: #1a202c;
    --text-muted: #64748b;
    --success: #27ae60;
    --danger: #c0392b;
    --warning: #f39c12;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    color: var(--text);
    background: var(--bg);
    line-height: 1.7;
    font-size: 15px;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 2rem; }}

  /* Header */
  .report-header {{
